// Day 3 question pool: Storage + databases. Data only; ids key saved stats, never rename or reuse.
window.QUIZ.push(
{id:"q03-001", day:3, dom:4, tags:["S3 storage classes & lifecycle"],
 q:"A media company stores product videos in S3 Standard. Each video is watched heavily for the first 30 days after upload and afterwards only about once a month, but playback must still start immediately. The videos must survive the loss of an Availability Zone. Which lifecycle transition is the most cost-effective?",
 o:["Transition objects to S3 One Zone-IA 30 days after creation","Transition objects to S3 Standard-IA 30 days after creation","Transition objects to S3 Glacier Instant Retrieval 30 days after creation","Transition objects to S3 Glacier Flexible Retrieval 30 days after creation"],
 a:[1],
 x:["One Zone-IA keeps data in a single Availability Zone, so the videos would be lost if that AZ were destroyed, which breaks the resilience requirement.","Standard-IA gives millisecond access, stores data across multiple AZs and suits data read about once a month, with lower retrieval charges than Glacier Instant Retrieval; 30 days is also the minimum object age for a lifecycle transition to an IA class.","Glacier Instant Retrieval has millisecond access but is designed for data read about once a quarter; at monthly reads its higher per-GB retrieval charges outweigh its lower storage price, and it bills a 90-day minimum storage duration.","Glacier Flexible Retrieval needs a restore that takes minutes to hours, so playback could not start immediately."],
 ref:["d3w1","d3c3","d3b2"], doc:"s3-classes"},
{id:"q03-002", day:3, dom:4, tags:["S3 storage classes & lifecycle"],
 q:"A data analytics startup stores datasets in Amazon S3. Some objects are read daily for weeks, others are never opened again after upload, and the team cannot predict which will be which. All objects need millisecond access, and the team wants to avoid retrieval fees and hand-tuned lifecycle rules. Which storage class is most cost-effective?",
 o:["S3 Intelligent-Tiering","S3 Standard-IA","S3 Standard","S3 Glacier Instant Retrieval"],
 a:[0],
 x:["Intelligent-Tiering monitors each object and moves it automatically between frequent, infrequent and archive instant access tiers, with millisecond access and no retrieval fees, which fits unknown or changing access patterns.","Standard-IA charges a per-GB retrieval fee, so the objects that are read daily would cost more than in Standard, and nothing moves between classes automatically.","Standard has no retrieval fees but charges the full frequent-access price for objects that are never read again.","Glacier Instant Retrieval has higher retrieval fees and a 90-day minimum storage duration, which is expensive for objects that are read daily."],
 ref:["d3w1","d3c3"], doc:"s3-classes"},
{id:"q03-003", day:3, dom:4, tags:["S3 storage classes & lifecycle"],
 q:"A healthcare provider must retain scanned patient records for 10 years to meet regulations. The records are almost never read; if an auditor requests one, delivering it within 48 hours is acceptable. Which storage option has the lowest cost?",
 o:["S3 Glacier Flexible Retrieval","S3 Glacier Instant Retrieval","S3 Glacier Deep Archive","S3 One Zone-IA"],
 a:[2],
 x:["Glacier Flexible Retrieval would meet the retrieval time, but its storage price is higher than Deep Archive, so it is not the cheapest option for data that is almost never read.","Glacier Instant Retrieval returns data in milliseconds, a speed the scenario does not need, and costs more to store than the colder Glacier classes.","Deep Archive is the lowest-cost S3 storage class, built for long-term retention; standard retrievals finish within 12 hours and bulk retrievals within 48 hours, both inside the allowed window.","One Zone-IA costs much more per GB than the Glacier classes for 10-year retention and keeps data in only one Availability Zone."],
 ref:["d3w1","d3c3"], doc:"s3-classes"},
{id:"q03-004", day:3, dom:4, tags:["S3 storage classes & lifecycle"],
 q:"A news organization keeps a large photo archive in Amazon S3. Each photo is requested roughly once a quarter, but when an editor needs one for a breaking story it must load in milliseconds. Which storage class minimizes cost while meeting this requirement?",
 o:["S3 Standard-IA","S3 Glacier Flexible Retrieval","S3 Glacier Deep Archive","S3 Glacier Instant Retrieval"],
 a:[3],
 x:["Standard-IA also offers millisecond access, but it costs more to store than Glacier Instant Retrieval, and data read only about once a quarter gains little from its lower retrieval fee.","Glacier Flexible Retrieval takes minutes (expedited) to hours (standard) to restore an object, so a photo could not load in milliseconds.","Deep Archive restores take up to 12 hours (standard) or 48 hours (bulk), far too slow for a breaking story.","Glacier Instant Retrieval is designed for long-lived data accessed about once a quarter that still needs millisecond retrieval, at a lower storage price than Standard-IA."],
 ref:["d3w1","d3c3"], doc:"s3-classes"},
{id:"q03-005", day:3, dom:4, tags:["S3 storage classes & lifecycle"],
 q:"An e-commerce site generates thumbnail images from original product photos that are kept in S3 Standard. The thumbnails are accessed infrequently, must load in milliseconds when requested, and can be regenerated from the originals if they are ever lost. Which storage class is most cost-effective for the thumbnails?",
 o:["S3 One Zone-IA","S3 Standard-IA","S3 Standard","S3 Glacier Flexible Retrieval"],
 a:[0],
 x:["One Zone-IA gives millisecond access at a lower price than Standard-IA by storing data in a single AZ, an acceptable trade-off for data that can be re-created.","Standard-IA pays for multi-AZ resilience that re-creatable thumbnails do not need, so it costs more than One Zone-IA.","Standard charges the frequent-access storage price, which is wasteful for thumbnails that are rarely requested.","Glacier Flexible Retrieval requires a restore that takes minutes to hours, so thumbnails would not load in milliseconds."],
 ref:["d3w1","d3c3"], doc:"s3-classes"},
{id:"q03-006", day:3, dom:4, tags:["S3 storage classes & lifecycle"],
 q:"A financial services company archives monthly transaction exports in Amazon S3. The exports are retrieved only a few times a year for audits, and when an audit starts the data must be available within 5 hours. The company wants the lowest storage cost that still meets this requirement. Which storage class should it use?",
 o:["S3 Glacier Deep Archive","S3 Glacier Flexible Retrieval","S3 Glacier Instant Retrieval","S3 Standard-IA"],
 a:[1],
 x:["Deep Archive is cheaper to store, but its standard retrievals take up to 12 hours and bulk retrievals up to 48 hours, which misses the 5-hour requirement.","Glacier Flexible Retrieval standard retrievals typically complete in 3–5 hours (expedited in 1–5 minutes), meeting the requirement at a lower storage price than the instant-access classes.","Glacier Instant Retrieval returns data in milliseconds, a speed that is not needed, and costs more to store than Flexible Retrieval.","Standard-IA provides millisecond access at a much higher storage price than the Glacier archive classes, so it is not the lowest-cost choice."],
 ref:["d3w1","d3c3"], doc:"s3-classes"},
{id:"q03-007", day:3, dom:4, tags:["S3 storage classes & lifecycle"],
 q:"A gaming company writes game-server logs to an S3 bucket. Engineers query the logs only during the first 30 days. After that, logs are kept for rare compliance reviews, for which waiting up to 48 hours for retrieval is acceptable, and they must be deleted after 5 years. Which two lifecycle rule actions together meet these requirements most cost-effectively? (Choose two.)",
 o:["Transition objects to S3 Glacier Deep Archive 30 days after creation","Transition objects to S3 Standard-IA 30 days after creation","Transition objects to S3 Glacier Instant Retrieval 30 days after creation","Expire objects 1,825 days (5 years) after creation","Transition objects to S3 One Zone-IA 30 days after creation"],
 a:[0,3],
 x:["Deep Archive is the cheapest storage class, and its retrieval times (within 12 hours standard, within 48 hours bulk) fit the rare compliance reviews.","Standard-IA provides millisecond access the reviews do not need and costs far more per GB than Deep Archive over 5 years.","Glacier Instant Retrieval is built for data that needs millisecond access about once a quarter; it costs more than Deep Archive for logs that can wait 48 hours.","An expiration action deletes the objects automatically at 5 years, meeting the deletion requirement without scripts.","One Zone-IA costs more than Deep Archive, offers instant access that is not needed, and keeps the logs in a single Availability Zone."],
 ref:["d3w1","d3b2","d3c3"], doc:"s3-classes"},
{id:"q03-008", day:3, dom:1, tags:["S3 features"],
 q:"A design agency stores client project files in an S3 bucket. Last week an employee overwrote several important files with empty versions, and another file was deleted by mistake; none of them could be recovered. The agency wants to be able to restore earlier versions of any object in the future with the least operational effort. What should a solutions architect do?",
 o:["Enable S3 Object Lock in compliance mode with a 10-year retention period","Add a lifecycle rule that transitions objects to S3 Glacier Flexible Retrieval","Enable S3 Versioning on the bucket","Enable S3 Transfer Acceleration on the bucket"],
 a:[2],
 x:["Compliance-mode Object Lock stops anyone, including the root user, from deleting locked object versions for 10 years, which blocks legitimate cleanup and goes far beyond the requirement.","A lifecycle transition only changes the storage class of the current object; it keeps no earlier versions, so overwrites and deletes still lose data.","With versioning, an overwrite creates a new version and a delete only adds a delete marker, so earlier versions can be restored at any time.","Transfer Acceleration speeds up long-distance uploads through edge locations; it does nothing to protect against overwrites or deletes."],
 ref:["d3w1","d3b1"], doc:"s3"},
{id:"q03-009", day:3, dom:4, tags:["S3 storage classes & lifecycle","S3 features"],
 q:"A company enabled S3 Versioning on a bucket that stores configuration exports updated many times a day. Storage costs have grown sharply because every update keeps the previous version. The company must be able to roll back any change made in the last 30 days but has no need for older versions. What is the most cost-effective solution?",
 o:["Suspend versioning on the bucket so that old versions stop accumulating","Add a lifecycle rule that permanently deletes noncurrent versions 30 days after they become noncurrent","Add a lifecycle rule that expires current versions of objects 30 days after creation","Add a lifecycle rule that transitions all objects to S3 Standard-IA after 30 days"],
 a:[1],
 x:["Suspending versioning keeps every existing old version, so costs do not drop, and it removes the ability to roll back future changes.","A noncurrent version expiration action removes old versions once they have been noncurrent for 30 days, keeping the 30-day rollback window while capping storage growth.","Expiring current versions targets the live configuration files (adding delete markers) and does not remove the old versions that drive the cost.","Standard-IA lowers the per-GB price but still keeps every old version indefinitely, so storage keeps growing."],
 ref:["d3w1","d3b1","d3b2"], doc:"s3"},
{id:"q03-010", day:3, dom:2, tags:["S3 features","Disaster recovery"],
 q:"A company stores invoices in an S3 bucket in eu-west-1. For disaster recovery, every newly uploaded invoice must be copied automatically to a bucket in eu-central-1. Which two actions must a solutions architect take? (Choose two.)",
 o:["Create a lifecycle rule on the source bucket that transitions objects to eu-central-1","Enable S3 Versioning on both the source and the destination buckets","Enable S3 Transfer Acceleration on the destination bucket","Enable MFA Delete on the source bucket","Add a Cross-Region Replication rule to the source bucket with an IAM role that S3 can assume"],
 a:[1,4],
 x:["Lifecycle rules change storage classes or expire objects within the same bucket; they cannot copy or move objects to another Region.","S3 Replication requires versioning to be enabled on both the source and the destination bucket.","Transfer Acceleration speeds up client uploads over long distances; it does not copy objects between buckets.","MFA Delete adds protection against deleting versions, but it is not required for replication and copies nothing.","A CRR rule makes S3 copy new objects asynchronously to the destination bucket in the other Region, using the IAM role for permissions."],
 ref:["d3w1","d3b1"], doc:"s3"},
{id:"q03-011", day:3, dom:1, tags:["S3 features","S3 security"],
 q:"A fintech company must keep all customer data inside a single AWS Region for data-residency reasons. The security team also wants an automatically maintained copy of every new object in a production S3 bucket stored in a separate AWS account, so the data survives even if the production account is compromised. Which solution meets these requirements?",
 o:["Configure S3 Cross-Region Replication to a bucket owned by the separate account","Enable S3 Versioning and MFA Delete on the production bucket only","Create a lifecycle rule that copies objects to a bucket in the separate account","Configure S3 Same-Region Replication to a bucket owned by the separate account"],
 a:[3],
 x:["Cross-Region Replication stores the copy in a different Region, which breaks the data-residency requirement.","Versioning and MFA Delete keep every version inside the production account, so there is still no independent copy outside the account that could be compromised.","Lifecycle rules can only transition or expire objects in the same bucket; they cannot copy objects to another account.","Same-Region Replication copies new objects automatically to a bucket in the same Region, and the destination bucket can belong to a different account, meeting both requirements."],
 ref:["d3w1","d3b1"], doc:"s3"},
{id:"q03-012", day:3, dom:1, tags:["S3 security"],
 q:"A company has dozens of S3 buckets in one AWS account, and developers create new buckets every week. After a bucket policy accidentally granted public read access, the security team wants to ensure that no current or future bucket in the account can be made public through bucket policies or ACLs. What should a solutions architect do?",
 o:["Turn on S3 Block Public Access settings at the account level","Turn on S3 Block Public Access on each existing bucket","Enable default encryption with SSE-S3 on every bucket","Enable S3 Versioning on every bucket in the account"],
 a:[0],
 x:["Account-level Block Public Access applies to every existing and future bucket in the account and overrides any bucket policy or ACL that would grant public access.","Bucket-level settings cover only the buckets you configure, and anyone with permission can turn them off on a single bucket, so they do not guarantee that future buckets stay private.","Encryption protects data at rest, but a public bucket policy still lets anyone read objects, because S3 decrypts SSE-S3 objects for authorized requests.","Versioning keeps object history; it has no effect on whether a bucket policy or ACL can grant public access."],
 ref:["d3w1","d3b1"], doc:"s3"},
{id:"q03-013", day:3, dom:3, tags:["S3 features"],
 q:"A video production studio uploads raw footage files of 20–40 GB each to Amazon S3. Uploads that send each file in a single PUT request fail, and when the network drops near the end of a long transfer the whole file has to be sent again. Which solution addresses both problems?",
 o:["Request a service quota increase for the maximum single PUT size","Enable S3 Versioning so that interrupted uploads can resume","Use S3 multipart upload and retry only the parts that fail","Upload the files to an EBS volume first and then copy them into the bucket"],
 a:[2],
 x:["The 5 GB maximum for a single PUT is a fixed S3 limit, not an adjustable quota, and raising it would not help with interrupted transfers anyway.","Versioning keeps multiple versions of completed objects; it does not let a partially uploaded object resume.","Multipart upload is required for objects larger than 5 GB (the S3 object maximum is now 50 TB); parts upload in parallel and a failed part can be resent without restarting the whole file.","Staging on EBS adds cost and a second transfer, and the final copy into S3 still needs multipart for files over 5 GB."],
 ref:["d3w1"], doc:"s3"},
{id:"q03-014", day:3, dom:3, tags:["EBS & instance store"],
 q:"A finance company is migrating a mission-critical Oracle database to Amazon EC2. The database needs consistent sub-millisecond latency, sustained IOPS well beyond what a single gp3 volume can provide, and the highest durability that Amazon EBS offers. Which EBS volume type should be used?",
 o:["General Purpose SSD (gp3) provisioned at its maximum IOPS","Provisioned IOPS SSD (io2 Block Express)","Throughput Optimized HDD (st1)","Instance store NVMe volumes in a RAID 0 array"],
 a:[1],
 x:["gp3 is the cost-effective default for most workloads, but the stated IOPS need exceeds a single gp3 volume, and its 99.8–99.9% durability is lower than io2.","io2 Block Express is built for critical, I/O-intensive databases, offering the highest provisioned IOPS, sub-millisecond latency and 99.999% durability.","st1 is a hard disk volume optimized for large sequential throughput, not the random, low-latency I/O a transactional database needs.","Instance store is very fast but ephemeral: data is lost if the instance stops or the host fails, which is unacceptable for a mission-critical database."],
 ref:["d3w1","d3c1"], doc:"ebs"},
{id:"q03-015", day:3, dom:4, tags:["EBS & instance store"],
 q:"A startup runs dozens of EC2 instances with General Purpose SSD (gp2) volumes. To get more IOPS for one application, the team has been creating volumes much larger than needed, because gp2 performance grows with volume size. Which change reduces cost while keeping or improving performance with the least effort?",
 o:["Modify the volumes to Provisioned IOPS SSD (io2)","Modify the volumes to Throughput Optimized HDD (st1)","Move the data to instance store volumes","Modify the volumes to General Purpose SSD (gp3)"],
 a:[3],
 x:["io2 delivers high IOPS but costs considerably more than gp3; it suits critical databases that need its durability and performance, not a general cost reduction.","st1 is an HDD volume for large sequential workloads; it performs poorly for random I/O and cannot be used as a boot volume.","Instance store is ephemeral, so data is lost when an instance stops or fails, and moving data there means rebuilding instances.","gp3 lets you provision IOPS and throughput independently of capacity at a lower price per GB than gp2, and Elastic Volumes can change the type in place without downtime."],
 ref:["d3w1","d3c1"], doc:"ebs"},
{id:"q03-016", day:3, dom:3, tags:["EBS & instance store"],
 q:"A company runs a log-processing cluster on Amazon EC2 that reads and writes large files sequentially. Each node needs several TiB of block storage that is accessed constantly, and the priority is high throughput at the lowest cost per GiB. Random I/O performance is not important, and the volumes are not used for booting. Which EBS volume type should the company choose?",
 o:["Throughput Optimized HDD (st1)","Cold HDD (sc1)","Provisioned IOPS SSD (io2)","General Purpose SSD (gp3)"],
 a:[0],
 x:["st1 is a low-cost HDD volume designed for frequently accessed, throughput-intensive sequential workloads such as log processing, big data and data warehouses.","sc1 is the cheapest volume type but is designed for infrequently accessed data and has much lower throughput, so it would bottleneck constantly accessed data.","io2 is priced for high random IOPS and low latency, which this sequential workload does not need, making it far more expensive per GiB.","gp3 performs well, but its price per GiB is higher than st1 for several TiB of sequential data, so it is not the lowest-cost fit."],
 ref:["d3w1","d3c1"], doc:"ebs"},
{id:"q03-017", day:3, dom:4, tags:["EBS & instance store"],
 q:"A research lab runs an application on Amazon EC2 that can only read data from block storage. It keeps several TiB of historical experiment data that is scanned sequentially only a few times a year. Which EBS volume type stores this data at the lowest cost?",
 o:["Throughput Optimized HDD (st1)","General Purpose SSD (gp3)","Cold HDD (sc1)","Provisioned IOPS SSD (io2)"],
 a:[2],
 x:["st1 is designed for frequently accessed sequential workloads; it costs more per GiB than sc1, which matters for data read only a few times a year.","gp3 is a solid default for active workloads but costs more per GiB than the HDD volume types for large, rarely read data.","sc1 is the lowest-cost EBS volume type, designed for large, infrequently accessed data that is read sequentially.","io2 is the most expensive volume type and provides high IOPS that rarely accessed archive data does not need."],
 ref:["d3w1","d3c1"], doc:"ebs"},
{id:"q03-018", day:3, dom:2, tags:["EBS & instance store"],
 q:"A company runs an EC2 instance in eu-west-1a with an attached 500 GiB EBS data volume. The data must be moved to a new instance that is running in eu-west-1b. What should a solutions architect do?",
 o:["Detach the volume and attach it to the new instance in eu-west-1b","Create a snapshot of the volume, create a new volume from it in eu-west-1b, and attach it","Enable EBS Multi-Attach so the instance in eu-west-1b can mount the volume","Use Elastic Volumes to change the Availability Zone of the existing volume"],
 a:[1],
 x:["An EBS volume lives in one Availability Zone and can be attached only to instances in that same AZ.","Snapshots are stored at the Region level, so you can create a new volume from a snapshot in any AZ of the Region and attach it to the instance there.","Multi-Attach (io1 and io2 only) lets instances in the same Availability Zone share a volume; it cannot span AZs.","Elastic Volumes changes a volume's size, type, IOPS or throughput, not its Availability Zone."],
 ref:["d3w1","d3c1"], doc:"ebs"},
{id:"q03-019", day:3, dom:3, tags:["EBS & instance store"],
 q:"A media company runs a video transcoding fleet on Amazon EC2. Each job writes large temporary files that need the fastest possible local disk I/O, and if an instance fails, the job simply restarts from the source video in Amazon S3. The team plans to use instance store volumes for the temporary files. Which two statements about instance store are correct? (Choose two.)",
 o:["It is storage physically attached to the host, giving very low latency and high I/O","It can be detached and reattached to a replacement instance after a failure","Its data is lost when the instance is stopped, hibernated, or terminated","It is automatically replicated to a second Availability Zone","It can be backed up natively with EBS snapshots"],
 a:[0,2],
 x:["Instance store disks sit on the physical host, so there is no network hop and I/O is very fast, which is ideal for scratch data.","Instance store volumes are tied to the host and cannot be detached or moved to another instance; only EBS volumes can.","Instance store is ephemeral: data survives a reboot but is lost on stop, hibernation, termination or disk failure, which is acceptable here because jobs can restart.","Instance store is not replicated anywhere; if copies are needed, the application has to create them.","EBS snapshots work only for EBS volumes; instance store data must be copied elsewhere, for example to S3, if it needs to be kept."],
 ref:["d3w1","d3c1"], doc:"ec2"},
{id:"q03-020", day:3, dom:2, tags:["EFS"],
 q:"A company runs a content management system on Linux EC2 instances in an Auto Scaling group spanning three Availability Zones. Every instance must read and write the same uploaded files at the same time, and storage should grow and shrink automatically without capacity planning. Which storage solution requires the least operational overhead?",
 o:["An EBS io2 volume with Multi-Attach enabled for all instances","Amazon FSx for Windows File Server with a file share for the instances","An NFS server on an EC2 instance with a large gp3 volume","An Amazon EFS file system with a mount target in each Availability Zone"],
 a:[3],
 x:["Multi-Attach works only for instances in a single Availability Zone, needs a cluster-aware file system, and the volume size must still be provisioned.","FSx for Windows File Server provides SMB shares for Windows workloads and needs provisioned storage capacity, so it fits neither Linux instances that need POSIX file access nor storage that sizes itself.","A self-managed NFS server is a single point of failure in one AZ, and you must patch it and resize its volume yourself.","EFS is a fully managed NFS file system that many Linux instances across AZs can mount at once, and it grows and shrinks automatically as files are added and removed."],
 ref:["d3p3","d3w1","d3c1"], doc:"efs"},
{id:"q03-021", day:3, dom:4, tags:["EFS"],
 q:"A company stores engineering project files on Amazon EFS. Monitoring shows that most files are not accessed after 60 days, but users occasionally open old files and expect them to be at the same path in the file system. Which solution reduces storage costs with the least effort?",
 o:["Enable EFS lifecycle management to move files unused for 60 days to EFS Infrequent Access","Run a nightly script that moves old files to S3 Glacier Deep Archive and deletes them from EFS","Create a new EFS One Zone file system and migrate all files to it","Move the old files to an EBS Cold HDD (sc1) volume attached to one instance"],
 a:[0],
 x:["Lifecycle management moves files that have not been accessed to the lower-cost IA storage class automatically; they keep the same path and remain readable, with a small per-access charge.","Deep Archive restores take hours, and the files would disappear from their file system path, which breaks the users' expectation and adds a script to maintain.","One Zone lowers the price of all data by giving up multi-AZ resilience and requires a migration, while doing nothing to target only the cold files.","An EBS volume attaches to instances in one AZ only and is not a shared file system, so users would lose access through the same path."],
 ref:["d3p3","d3w1"], doc:"efs"},
{id:"q03-022", day:3, dom:3, tags:["FSx"],
 q:"A company is migrating a Windows-based line-of-business application to AWS. The application stores documents on SMB file shares and relies on Microsoft Active Directory for authentication and Windows ACLs for permissions. The company wants a fully managed file system that stays available if an Availability Zone fails. Which solution meets these requirements?",
 o:["Amazon EFS with a mount target in each Availability Zone","Amazon FSx for Lustre linked to an S3 bucket","Amazon FSx for Windows File Server in a Multi-AZ deployment","An S3 bucket accessed through an S3 File Gateway SMB share"],
 a:[2],
 x:["EFS is an NFS file system for Linux clients; it does not provide SMB shares or Windows ACLs.","FSx for Lustre is a high-performance file system for Linux HPC and ML workloads and does not offer SMB shares with Active Directory integration.","FSx for Windows File Server provides fully managed native SMB shares that join Active Directory and enforce Windows ACLs, and a Multi-AZ deployment fails over automatically.","S3 File Gateway is a hybrid appliance that gives on-premises applications file access to S3 objects; it is not a managed, Multi-AZ Windows file server for applications running in AWS."],
 ref:["d3w1","d3c1"], doc:"fsx-windows"},
{id:"q03-023", day:3, dom:3, tags:["FSx"],
 q:"A pharmaceutical company runs genome-analysis jobs on hundreds of EC2 instances at once. The input datasets are stored in an S3 bucket. The jobs need a shared POSIX file system with sub-millisecond latency and very high parallel throughput, and results must be written back to the bucket. Which storage solution best meets these requirements?",
 o:["Amazon EFS with Elastic throughput mode","Amazon FSx for Lustre linked to the S3 bucket","Amazon FSx for Windows File Server","EBS gp3 volumes attached to each instance"],
 a:[1],
 x:["EFS is a good general-purpose shared file system, but it is not a parallel HPC file system and cannot match Lustre's latency and aggregate throughput for hundreds of instances.","FSx for Lustre is a parallel file system for HPC and ML that can lazy-load data from a linked S3 bucket and export results back to it.","FSx for Windows File Server serves SMB shares to Windows workloads; it is not designed for Linux HPC clusters or S3 data integration.","Separate EBS volumes are not shared, so every instance would need its own copy of the data and results would have to be merged manually."],
 ref:["d3w1","d3c1"], doc:"fsx-lustre"},
{id:"q03-024", day:3, dom:3, tags:["FSx"],
 q:"A company is migrating its on-premises NetApp storage to AWS. The same datasets are served to Linux servers over NFS and to Windows servers over SMB, and a database server uses iSCSI block storage from the same system. The company wants a fully managed service that keeps NetApp features such as SnapMirror replication, with minimal changes to its processes. Which service should it use?",
 o:["Amazon FSx for OpenZFS","Amazon FSx for Windows File Server","Amazon EFS","Amazon FSx for NetApp ONTAP"],
 a:[3],
 x:["FSx for OpenZFS serves files over NFS; it cannot provide SMB shares, iSCSI block storage or NetApp features such as SnapMirror.","FSx for Windows File Server serves SMB shares and does not support NFS clients, iSCSI block storage or SnapMirror.","EFS provides NFS access for Linux only, with no SMB, block storage or NetApp data management features.","FSx for NetApp ONTAP is a managed ONTAP file system that serves NFS, SMB and iSCSI at the same time and keeps ONTAP features such as snapshots, SnapMirror and storage efficiency."],
 ref:["d3w1","d3c1"]},
{id:"q03-025", day:3, dom:3, tags:["FSx"],
 q:"A software company runs Linux build servers that use an on-premises ZFS file server over NFS. Its workflows depend on ZFS snapshots and instant clones to create copies of datasets for testing, and builds need very low latency. The company wants a fully managed AWS service and does not want to change its ZFS-based workflows. Which service should it choose?",
 o:["Amazon FSx for OpenZFS","Amazon FSx for Lustre","Amazon EFS","Amazon FSx for Windows File Server"],
 a:[0],
 x:["FSx for OpenZFS is a fully managed ZFS file system accessed over NFS, with ZFS snapshots, clones and very low latency, so existing workflows move with little change.","FSx for Lustre is a parallel file system for HPC and ML; it does not offer ZFS snapshots and clones.","EFS is a managed NFS file system, but it does not expose ZFS features such as snapshots and instant clones, so the workflows would have to change.","FSx for Windows File Server serves SMB shares for Windows clients, not ZFS datasets over NFS for Linux build servers."],
 ref:["d3w1","d3c1"]},
{id:"q03-026", day:3, dom:3, tags:["Storage Gateway"],
 q:"A manufacturing company has an on-premises application that writes sensor export files to an NFS share. The company wants the files stored durably as objects in Amazon S3 so that cloud analytics services can process them, while the application keeps using NFS with low-latency access to recently written files. Which solution meets these requirements?",
 o:["Deploy Volume Gateway with cached volumes and attach them over iSCSI","Deploy Tape Gateway and write the files to virtual tapes","Deploy S3 File Gateway and expose an NFS file share backed by the bucket","Mount an Amazon EFS file system over a Site-to-Site VPN connection"],
 a:[2],
 x:["Volume Gateway presents iSCSI block volumes, and the data is stored as volume data, not as individual files that analytics services can read as S3 objects.","Tape Gateway emulates a tape library for backup software; files written to virtual tapes cannot be read as individual S3 objects.","S3 File Gateway presents NFS or SMB shares on premises, stores each file as an S3 object, and keeps a local cache for low-latency access to recent data.","EFS stores files in a file system, not as S3 objects, and every access would cross the VPN with no local cache."],
 ref:["d3w1"], doc:"storagegateway"},
{id:"q03-027", day:3, dom:4, tags:["Storage Gateway"],
 q:"A company's on-premises application uses iSCSI block storage, and the local storage array is almost full. The company wants to keep the primary copy of the data in AWS while keeping low-latency access to the most frequently used data on premises, without buying more local storage. Which solution meets these requirements?",
 o:["Volume Gateway with stored volumes","Volume Gateway with cached volumes","S3 File Gateway with an NFS share","Tape Gateway with a virtual tape library"],
 a:[1],
 x:["Stored volumes keep the entire dataset on premises and only back it up asynchronously to AWS, so they would still need more local capacity.","Cached volumes keep the primary data in S3 and cache frequently accessed data locally, which frees local capacity while keeping hot data fast.","S3 File Gateway provides file shares over NFS or SMB, not the iSCSI block volumes the application requires.","Tape Gateway provides virtual tapes for backup software, not live block volumes for an application."],
 ref:["d3w1"], doc:"storagegateway"},
{id:"q03-028", day:3, dom:4, tags:["Storage Gateway"],
 q:"A company backs up its on-premises servers to a physical tape library using commercial backup software. Handling and shipping tapes off site is slow and costly. The company wants to stop using physical tapes without changing its backup software or job configuration, and to archive old backups at the lowest possible cost. Which solution meets these requirements?",
 o:["S3 File Gateway, pointing backup jobs at an SMB share","Volume Gateway with stored volumes as the backup target","Amazon EFS mounted over a VPN as the backup target","Tape Gateway, archiving virtual tapes to S3 Glacier Deep Archive"],
 a:[3],
 x:["Writing to an SMB share means reconfiguring the backup jobs from tape to disk targets, which the company wants to avoid.","Stored volumes present iSCSI disks, not a tape library, so the backup jobs would have to be reconfigured, and the primary data stays on premises.","EFS is a network file system, so backups would need new disk-based job targets and would run over the VPN with no tape emulation.","Tape Gateway presents a virtual tape library that existing backup software uses as is, stores virtual tapes in S3, and can archive them to Glacier Deep Archive for the lowest cost."],
 ref:["d3w1"], doc:"storagegateway"},
{id:"q03-029", day:3, dom:2, tags:["RDS","High availability design"],
 q:"An online retailer runs its order database on a Single-AZ Amazon RDS for PostgreSQL DB instance. The database must fail over automatically if its Availability Zone fails, and analysts' heavy read-only reporting queries are slowing down order processing. Which two actions should a solutions architect take? (Choose two.)",
 o:["Increase the automated backup retention period to 35 days","Send the reporting queries to the standby of a Multi-AZ DB instance","Convert the DB instance to a Multi-AZ DB instance deployment","Enable storage autoscaling on the DB instance","Create a read replica and point the reporting tools at its endpoint"],
 a:[2,4],
 x:["Longer backup retention widens the point-in-time restore window, but a restore is a manual recovery, not automatic failover, and it does nothing for read load.","In a Multi-AZ DB instance deployment the standby only receives synchronous replication and cannot serve read traffic.","Multi-AZ keeps a synchronous standby in another AZ and fails over to it automatically, keeping the same DNS endpoint.","Storage autoscaling adds disk space when the volume fills up; it neither adds failover nor offloads queries.","A read replica receives asynchronous updates and can serve the read-only reporting queries, taking that load off the primary."],
 ref:["d3p1","d3c2","d3w2"], doc:"rds"},
{id:"q03-030", day:3, dom:2, tags:["RDS"],
 q:"At 14:20 a developer accidentally ran a script that deleted thousands of rows from a production Amazon RDS for MySQL database. The DB instance is Multi-AZ, has one read replica, and has automated backups enabled with a 7-day retention period. The company wants the data back as it was at 14:15 with the least data loss. What should a solutions architect do?",
 o:["Perform a point-in-time restore to 14:15 into a new DB instance","Force a Multi-AZ failover so that the standby becomes the primary","Promote the read replica to a standalone DB instance","Restore the most recent automated daily snapshot to a new instance"],
 a:[0],
 x:["Point-in-time restore combines the daily snapshot with transaction logs to recreate the database at any second within the retention period, so 14:15 can be recovered; it always creates a new DB instance.","The standby is updated synchronously, so it already contains the deletion; failover only changes which copy serves traffic.","The read replica has already applied the deletion through replication, so promoting it does not bring the rows back.","The daily snapshot may be many hours old, so restoring it alone would lose every change made between the snapshot and 14:15."],
 ref:["d3p1","d3w2"], doc:"rds"},
{id:"q03-031", day:3, dom:1, tags:["RDS"],
 q:"A healthcare company must keep a monthly backup of its Amazon RDS for PostgreSQL database for 7 years to meet compliance rules. Automated backups are already enabled. What should a solutions architect do to meet the retention requirement?",
 o:["Set the automated backup retention period to 7 years","Create a read replica each month and keep it running","Take a manual DB snapshot each month and keep it for 7 years","Convert the DB instance to a Multi-AZ deployment"],
 a:[2],
 x:["Automated backups can be retained for a maximum of 35 days, so a 7-year retention period is not possible.","Read replicas keep replicating ongoing changes, so they are not point-in-time backups, and running dozens of them would be very expensive.","Manual snapshots are not subject to the automated retention limit and remain until you delete them, so monthly snapshots can be kept for 7 years (a scheduled job or an AWS Backup plan can create them).","Multi-AZ improves availability with a standby instance, but it does not keep historical backups."],
 ref:["d3p1","d3w2"], doc:"rds"},
{id:"q03-032", day:3, dom:1, tags:["RDS","KMS & encryption"],
 q:"A company has an unencrypted Amazon RDS for MySQL DB instance. A new security policy requires every database to be encrypted at rest with AWS KMS. What should a solutions architect do to bring this database into compliance?",
 o:["Modify the DB instance to turn on encryption at rest with a KMS key","Restore a new DB instance from an encrypted copy of a snapshot","Create an encrypted read replica and promote it to a standalone instance","Enable default encryption on the S3 bucket that stores the RDS backups"],
 a:[1],
 x:["Encryption at rest can only be chosen when a DB instance is created; an existing unencrypted instance cannot be modified to enable it.","Copying a snapshot lets you enable encryption with a KMS key, and a DB instance restored from the encrypted copy is encrypted; the application is then pointed at the new instance.","RDS does not allow an encrypted read replica of an unencrypted DB instance, so this path is not possible.","RDS keeps backups in AWS-managed storage, not in a customer bucket, and the database volume itself would remain unencrypted."],
 ref:["d3w2","d3p1"], doc:"rds"},
{id:"q03-033", day:3, dom:3, tags:["RDS"],
 q:"A company runs a Microsoft SQL Server database on premises with many T-SQL stored procedures and SQL Server Agent jobs. It wants to move to AWS with minimal code changes and have AWS handle patching, backups, and automatic failover across Availability Zones. Which solution meets these requirements?",
 o:["Amazon Aurora MySQL-Compatible Edition with Aurora Replicas","SQL Server installed on EC2 instances in two Availability Zones","Amazon DynamoDB with global secondary indexes","Amazon RDS for SQL Server with a Multi-AZ deployment"],
 a:[3],
 x:["Aurora supports only MySQL- and PostgreSQL-compatible engines, so the T-SQL code and Agent jobs would need to be rewritten.","SQL Server on EC2 keeps the engine, but the company would have to manage patching, backups and failover itself, which it wants to avoid.","DynamoDB is a NoSQL key-value store; moving a relational SQL Server database to it would require a complete redesign.","RDS for SQL Server runs the same engine, supports SQL Server Agent, and provides managed patching, automated backups and Multi-AZ failover."],
 ref:["d3w2","d3p1"], doc:"rds"},
{id:"q03-034", day:3, dom:2, tags:["RDS","Disaster recovery"],
 q:"A travel booking company runs Amazon RDS for MySQL in eu-west-1. It needs a disaster recovery copy in us-east-1 with an RPO of a few minutes, and it would like to serve read-only traffic to North American users from that copy in the meantime. Which solution meets these requirements?",
 o:["Create a cross-Region read replica in us-east-1","Convert the DB instance to a Multi-AZ deployment","Copy the automated snapshots to us-east-1 once a day","Increase the automated backup retention period to 35 days"],
 a:[0],
 x:["A cross-Region read replica is updated asynchronously, usually within seconds to minutes, serves local reads, and can be promoted to a standalone primary during a Regional outage.","Multi-AZ protects against an Availability Zone failure inside the same Region, not against losing eu-west-1.","Daily snapshot copies give an RPO of up to 24 hours and cannot serve read traffic until a database is restored from them.","Longer retention keeps backups in the same Region and does not create a usable copy in us-east-1."],
 ref:["d3p1","d3w2"], doc:"rds"},
{id:"q03-035", day:3, dom:2, tags:["Aurora"],
 q:"A company plans to replace a self-managed MySQL database with Amazon Aurora MySQL-Compatible Edition. The team asks how Aurora's storage and replicas differ from traditional MySQL replication. Which two statements are correct? (Choose two.)",
 o:["Each Aurora Replica keeps its own full copy of the data, synchronized through binary log replication","Aurora keeps six copies of the data across three Availability Zones in a shared cluster volume","Aurora storage must be provisioned in advance and resized manually as the data grows","Aurora Replicas read from the same shared volume as the writer and can be promoted during failover","Aurora offers MySQL-, PostgreSQL-, Oracle- and SQL Server-compatible editions"],
 a:[1,3],
 x:["Aurora Replicas do not hold separate copies; they share the cluster volume with the writer, which is why replica lag is typically very low.","Aurora's distributed storage writes six copies across three AZs, so it tolerates the loss of an entire AZ without losing data.","The Aurora cluster volume grows automatically as data is added, so no storage provisioning is required.","Because replicas share the writer's storage, they stay closely in sync (usually under 100 ms of lag), and Aurora promotes one automatically if the writer fails.","Aurora is compatible only with MySQL and PostgreSQL; Oracle and SQL Server run on Amazon RDS instead."],
 ref:["d3w2"], doc:"aurora"},
{id:"q03-036", day:3, dom:4, tags:["Aurora"],
 q:"A startup is launching a SaaS project-management application that needs a PostgreSQL-compatible database. Usage is unpredictable: close to zero at night and on weekends, with sudden spikes when large customers onboard. The company wants to avoid paying for idle capacity and does not want to manage instance sizes. Which option is most cost-effective?",
 o:["An Aurora PostgreSQL provisioned cluster sized for the expected peak","Amazon RDS for PostgreSQL with Reserved Instances for the peak size","Amazon Aurora Serverless v2 with PostgreSQL compatibility","Amazon DynamoDB in on-demand capacity mode"],
 a:[2],
 x:["A cluster sized for peak keeps paying for that capacity during the long idle periods.","Reserved Instances lower the hourly rate in exchange for a commitment to fixed capacity, which still means paying for peak capacity that sits idle most of the time.","Aurora Serverless v2 scales capacity up and down automatically in fine-grained increments based on load, so the company pays mainly for what it uses and never sizes instances.","DynamoDB scales automatically and bills per request, but it is not PostgreSQL-compatible, so the application would need a redesign."],
 ref:["d3w2"], doc:"aurora"},
{id:"q03-037", day:3, dom:3, tags:["Aurora"],
 q:"An Amazon Aurora MySQL cluster has one writer and three Aurora Replicas. The application sends every query to the cluster endpoint, so the writer is overloaded while the replicas sit mostly idle. Most of the traffic is read-only. What is the simplest way to spread the read traffic across the replicas?",
 o:["Send read-only queries to the cluster's reader endpoint","Place an Application Load Balancer in front of the replicas","Convert the cluster to an RDS Multi-AZ DB instance deployment","Create Route 53 weighted records for each replica's instance endpoint"],
 a:[0],
 x:["The reader endpoint load-balances connections across the available Aurora Replicas and updates automatically when replicas are added or removed.","An ALB routes HTTP and HTTPS traffic and cannot balance MySQL database connections.","The standby of an RDS Multi-AZ DB instance does not serve reads, so this would remove read capacity instead of using it.","Weighted records could spread connections, but you would have to maintain them by hand as replicas change, which is more work than the built-in reader endpoint."],
 ref:["d3w2"], doc:"aurora"},
{id:"q03-038", day:3, dom:4, tags:["DynamoDB"],
 q:"A ticketing startup is launching a new event-sales app on Amazon DynamoDB. Traffic is unpredictable: the app may be quiet for days and then spike sharply when a popular concert goes on sale. The team wants no capacity planning and to pay only for the reads and writes the app actually performs. Which configuration should it use?",
 o:["Provisioned capacity sized for the expected peak","Provisioned capacity with DynamoDB auto scaling","Provisioned capacity with reserved capacity purchased","On-demand capacity mode"],
 a:[3],
 x:["Capacity sized for peak is paid for every hour, including the many quiet days.","Auto scaling suits gradual, predictable changes and is often cheaper for steady traffic, but it reacts over minutes and still needs minimum and maximum settings, so sudden spikes can be throttled.","Reserved capacity is a commitment that lowers the price of steady provisioned throughput; it is the opposite of paying only for actual use.","On-demand mode bills per request and adapts automatically to traffic with no capacity to plan, which fits new and spiky workloads."],
 ref:["d3p2","d3b3","d3w2"], doc:"dynamodb"},
{id:"q03-039", day:3, dom:3, tags:["DynamoDB"],
 q:"An e-commerce application stores orders in a DynamoDB table with partition key CustomerId and sort key OrderDate. The page that shows one customer's orders from the last 30 days has become slow and expensive as the table grew, because the code reads the entire table and then filters the results. What should a solutions architect recommend?",
 o:["Keep the Scan and add a FilterExpression on CustomerId and OrderDate","Use a Query on CustomerId with a sort key condition on OrderDate","Put a DAX cluster in front of the table and keep the Scan","Switch the table from provisioned to on-demand capacity"],
 a:[1],
 x:["A filter expression is applied after items are read, so the Scan still reads, and is charged for, every item in the table.","A Query reads only the items in one partition that match the sort key condition, so cost and latency depend on the customer's orders, not on the size of the table.","DAX can cache results, but every cache miss still runs a full table Scan, so the inefficient access pattern remains.","On-demand changes how capacity is billed, but a Scan still reads every item, so the page stays slow and costly."],
 ref:["d3p2","d3b3"], doc:"dynamodb"},
{id:"q03-040", day:3, dom:3, tags:["DynamoDB"],
 q:"An IoT company writes sensor readings to a DynamoDB table that uses the current date (for example, 2026-10-12) as the partition key. Writes are throttled even though the table is far below its total provisioned write capacity. Which two changes would best spread the write load? (Choose two.)",
 o:["Use a high-cardinality partition key such as DeviceId","Add a local secondary index on the date attribute","Put a DAX cluster in front of the DynamoDB table","Read the table with parallel Scan segments","Add a random suffix to each date partition key value"],
 a:[0,4],
 x:["With many distinct DeviceId values, writes are spread across many partitions instead of all landing on the one holding today's date.","A local secondary index uses the same partition key, so writes still concentrate on today's partition, and the index adds extra write cost.","DAX is an in-memory cache for reads; writes still go to the same hot partition in the table.","Parallel Scan speeds up reading a whole table and does nothing for write throttling.","Write sharding with a suffix (for example 2026-10-12.1 to 2026-10-12.10) spreads one day's writes across several partition key values."],
 ref:["d3p2","d3w2"], doc:"dynamodb"},
{id:"q03-041", day:3, dom:3, tags:["DynamoDB"],
 q:"A gaming company stores player profiles in a DynamoDB table with PlayerId as the partition key. A new login feature must find a player by email address with low latency, and scanning the table is too slow. What is the most efficient solution?",
 o:["Create a local secondary index with Email as the sort key","Use a Scan with a FilterExpression on the Email attribute","Create a global secondary index with Email as the partition key","Export the table to Amazon Redshift and query it by email"],
 a:[2],
 x:["A local secondary index keeps PlayerId as its partition key, so you still need the PlayerId to query it, and an LSI can only be created together with the table.","A Scan with a filter still reads every item in the table, which is the slow, expensive behavior the team wants to avoid.","A global secondary index can be added to an existing table and lets you Query directly by Email with low latency.","Redshift is a data warehouse for analytics; it is not suited to low-latency lookups on every login."],
 ref:["d3p2","d3w2"], doc:"dynamodb"},
{id:"q03-042", day:3, dom:4, tags:["DynamoDB"],
 q:"A web application stores user sessions in a DynamoDB table, and each item has an attribute holding its expiry time as a Unix epoch timestamp. The application already ignores expired sessions when reading. Today a scheduled Lambda function scans the table every hour and deletes expired items, which consumes capacity and adds cost. Which solution removes expired items with the least cost and operational effort?",
 o:["Run the Lambda function every 5 minutes instead of every hour","Enable DynamoDB Streams and delete items from the stream consumer","Add a lifecycle rule that expires items after 24 hours","Enable Time to Live (TTL) on the expiry time attribute"],
 a:[3],
 x:["Running the cleanup more often consumes even more read and write capacity and keeps the custom code to maintain.","Streams emit a record when an item changes; they do not find expired items, so custom deletion code would still be needed.","Lifecycle rules are an S3 feature; DynamoDB tables do not have lifecycle rules.","TTL deletes items in the background after their timestamp passes (typically within a few days) without consuming write capacity, and the app already filters out expired items."],
 ref:["d3p2","d3w2"], doc:"dynamodb"},
{id:"q03-043", day:3, dom:3, tags:["DynamoDB","Caching"],
 q:"A retail company's product catalog runs on DynamoDB. During flash sales the same items are read millions of times, and the business wants read latency cut from single-digit milliseconds to microseconds with minimal application changes. Which solution meets these requirements?",
 o:["Add a DynamoDB Accelerator (DAX) cluster and point the DynamoDB client at it","Add an ElastiCache for Valkey cluster and write custom caching logic","Create DynamoDB read replicas in additional Availability Zones","Switch the table from provisioned to on-demand capacity mode"],
 a:[0],
 x:["DAX is an in-memory cache built for DynamoDB that serves cached reads in microseconds and is API-compatible, so only the client configuration changes.","ElastiCache could cache items, but the application would need new caching, invalidation and serialization code, which is more change than DAX requires.","DynamoDB has no per-AZ read replicas to create; it already replicates every table across multiple AZs, and extra copies would not cut read latency to microseconds.","On-demand mode changes how throughput is billed and scaled, not the latency of individual reads."],
 ref:["d3w2","d3c4"], doc:"dynamodb"},
{id:"q03-044", day:3, dom:3, tags:["DynamoDB"],
 q:"A real estate startup stores property listings in DynamoDB. The team wants to attach up to 20 high-resolution photos of several MB each to every listing, but the writes fail because the items become too large. Which design is most appropriate?",
 o:["Request a service quota increase for the maximum DynamoDB item size","Store the photos in Amazon S3 and save their object keys in the item","Base64-encode each photo and split it across many DynamoDB items","Move the listings and photos into an Amazon Redshift cluster"],
 a:[1],
 x:["The 400 KB maximum item size is a fixed DynamoDB limit that cannot be raised.","Keeping large binary objects in S3 and storing only their keys and metadata in DynamoDB is the standard pattern; S3 stores large objects durably at low cost.","Splitting photos into chunks works around the limit with complex code and costs far more in read and write capacity than S3 storage.","Redshift is a data warehouse for analytics, not a store for application images and low-latency listing lookups."],
 ref:["d3p2","d3w2"], doc:"dynamodb"},
{id:"q03-045", day:3, dom:3, tags:["Caching"],
 q:"A game studio is choosing between Amazon ElastiCache for Valkey and ElastiCache for Memcached for a new in-memory layer. Which two requirements would make ElastiCache for Valkey the better choice? (Choose two.)",
 o:["Caching simple string results of database queries","Keeping a real-time player leaderboard with sorted sets","Pushing match events to game servers with pub/sub messaging","Getting sub-millisecond read latency from memory","Running the cache inside private subnets of a VPC"],
 a:[1,2],
 x:["Simple key-value caching of query results works well on both engines, so it does not favor Valkey.","Valkey, like Redis OSS, supports rich data structures such as sorted sets, which make leaderboards simple; Memcached stores only plain key-value pairs.","Valkey supports pub/sub messaging; Memcached has no messaging features.","Both engines are in-memory and deliver sub-millisecond latency, so this does not distinguish them.","Both engines run inside your VPC subnets, so this requirement is met either way."],
 ref:["d3w2","d3c4"], doc:"elasticache"},
{id:"q03-046", day:3, dom:2, tags:["Caching","High availability design"],
 q:"A company runs a web application on EC2 instances in an Auto Scaling group behind an Application Load Balancer. Sessions are kept in each instance's memory, so users are logged out whenever scale-in terminates their instance. The company needs a fast, shared session store that keeps working if a single cache node fails. Which solution meets these requirements?",
 o:["Enable sticky sessions on the Application Load Balancer","Store sessions on an EBS volume attached to each instance","Store sessions on each instance's instance store volume","Store sessions in ElastiCache for Valkey with Multi-AZ replicas"],
 a:[3],
 x:["Sticky sessions keep a user on the same instance, but the session is still lost when that instance is terminated.","Each EBS volume belongs to one instance, so sessions are not shared and remain tied to that instance's lifecycle.","Instance store is local to each instance and is lost when the instance stops or terminates, so sessions would still disappear.","ElastiCache for Valkey gives every instance a shared in-memory session store, and replicas in other AZs with automatic failover keep it available if a node fails."],
 ref:["d3w2","d3c4"], doc:"elasticache"},
{id:"q03-047", day:3, dom:3, tags:["Caching","RDS"],
 q:"A news website's article pages run the same complex SQL queries against an Amazon RDS for MySQL database thousands of times per minute. Database CPU is constantly high, and the business wants page data returned with sub-millisecond latency. Which solution is most effective?",
 o:["Cache query results in Amazon ElastiCache using lazy loading with a TTL","Add RDS read replicas and spread the queries across them","Add a DynamoDB Accelerator (DAX) cluster in front of the database","Convert the DB instance to a Multi-AZ deployment"],
 a:[0],
 x:["ElastiCache serves repeated query results from memory in sub-millisecond time and removes most of the repeated work from the database; the TTL keeps cached data fresh.","Read replicas spread the load, but each query still runs against a disk-based database with millisecond latency and repeats the same expensive work.","DAX works only with DynamoDB tables, not with RDS databases.","Multi-AZ adds a standby for failover; in a Multi-AZ DB instance deployment the standby serves no queries, so CPU load stays the same."],
 ref:["d3w2","d3c4"], doc:"elasticache"},
{id:"q03-048", day:3, dom:3, tags:["Redshift"],
 q:"A retail company runs its order-processing system on Amazon RDS for PostgreSQL. Business analysts want to run complex aggregation queries over five years of sales history combined with data from the marketing and inventory systems, using SQL-based BI tools. Running these queries on the production database slows down order processing. Which service should the company use for this analytics workload?",
 o:["Amazon DynamoDB with global secondary indexes","An RDS for PostgreSQL read replica of the order database","Amazon Redshift as a central data warehouse","Amazon ElastiCache for Valkey"],
 a:[2],
 x:["DynamoDB is built for key-value access at scale; it does not support the joins and large aggregations the analysts need.","A read replica offloads the production database, but it holds only the order data and is a row-based OLTP engine, not built for combining sources and scanning years of history.","Redshift is a columnar data warehouse built for complex SQL analytics over large volumes of data loaded from many sources, and it works with standard BI tools.","ElastiCache is an in-memory cache for fast lookups, not a place to store and analyze years of historical data."],
 ref:["d3w2"], doc:"redshift"},
{id:"q03-049", day:3, dom:3, tags:["Purpose-built databases"],
 q:"A bank wants to detect fraud rings by analyzing relationships between accounts, devices, phone numbers, and transactions, often following connections several hops deep in real time. Relational queries with many self-joins have become too slow. Which database service is the best fit?",
 o:["Amazon Redshift","Amazon Neptune","Amazon DynamoDB","Amazon Aurora PostgreSQL"],
 a:[1],
 x:["Redshift is optimized for analytical aggregations over large tables, not real-time traversals of highly connected data.","Neptune is a managed graph database designed to store relationships and traverse many hops quickly with graph query languages such as Gremlin and openCypher.","DynamoDB excels at key-value lookups, but multi-hop relationship traversals would need many sequential requests and complex application code.","Aurora is a relational database, so it runs into the same many-join performance problem the bank already has."],
 ref:["d3w2"]},
{id:"q03-050", day:3, dom:3, tags:["Purpose-built databases"],
 q:"A company's product catalog application uses MongoDB on self-managed EC2 instances. The team wants a fully managed AWS database that works with its existing MongoDB drivers and queries and stores flexible JSON documents, with minimal code changes. Which service should it choose?",
 o:["Amazon DynamoDB","Amazon Neptune","Amazon RDS for MySQL with JSON columns","Amazon DocumentDB"],
 a:[3],
 x:["DynamoDB can store JSON-like documents, but it has its own API, so the MongoDB drivers and queries would have to be rewritten.","Neptune is a graph database for highly connected data, not a document store for a MongoDB application.","MySQL JSON columns would require replacing the MongoDB drivers and rewriting the queries in SQL.","DocumentDB is a fully managed document database that is compatible with MongoDB drivers and APIs, so the application needs minimal changes."],
 ref:["d3w2"]}
);
